    if not lines:
        return ""

    n, m = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:n+1]]

    # Find all connected components
    visited = [[False] * m for _ in range(n)]
    result = [row[:] for row in grid]

    def dfs(r, c):
        comp = []
        stack = [(r, c)]
        while stack:
            cr, cc = stack.pop()
            if not visited[cr][cc] and grid[cr][cc] == '.':
                visited[cr][cc] = True
                comp.append((cr, cc))
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < n and 0 <= nc < m and not visited[nr][nc] and grid[nr][nc] == '.':
                        stack.append((nr, nc))
        return comp

    for r in range(n):
        for c in range(m):
            if grid[r][c] == '.' and not visited[r][c]:
                comp = dfs(r, c)
                if not comp:
                    continue
                min_r, max_r = min(c[0] for c in comp), max(c[0] for c in comp)
                min_c, max_c = min(c[1] for c in comp), max(c[1] for c in comp)
