def solve_game(node, cache):
    if (id(node), -1, -1) in cache:
        return cache[(id(node), -1, -1)]

    if isinstance(node, LeafNode):
        return node.value, 1

    left_res, left_ops = solve_game(node.left, cache)
    right_res, right_ops = solve_game(node.right, cache)

    if isinstance(node, InternalNode):
        total_ops = left_ops + right_ops + 1
        if total_ops % 2 == 1:
            result = max(left_res, right_res)
        else:
            result = min(left_res, right_res)
        return result, total_ops

    return node.value, 1

