def max_weight_subgraph(input_data):
    """
    Computes the maximum weight of a subgraph using min-cut.

    The problem is modeled as: maximize sum(edge weights in subgraph) - sum(vertex weights in subgraph)

    This is equivalent to: (total edge weight) - min_cut

    Construction:
    - Source S, Sink T
    - S -> i with capacity a_i for each vertex i
    - Bidirectional edges u -> v and v -> u with capacity w for each edge (u,v) with weight w
    """
    lines = input_data.strip().split('\n')

    # Parse n and m
    n, m = map(int, lines[0].split())

    # Parse vertex weights
    vertex_weights = list(map(int, lines[1].split()))

    # Parse edges
    edges = []
    for i in range(2, 2 + m):
        v, u, w = map(int, lines[i].split())
        edges.append((v, u, w))

    if m == 0:
        return 0

    # Build the flow network
    # Total edge weight
    total_edge_weight = sum(w for v, u, w in edges)

    # Compute min-cut using the constructed graph
    min_cut = compute_min_cut(n, edges, vertex_weights)

    # Maximum weight = total edge weight - min_cut
    result = total_edge_weight - min_cut

    # Don't go negative (though theoretically shouldn't happen)
    return max(result, 0)


class Node:
    """Base class for graph nodes"""
    def __init__(self, index):
        self.index = index
        self.adj = dict()
        self.capacity_in = 0
        self.flow_in = 0

    def add_edge(self, target):
        if not isinstance(target, Node):
