        return target


def compute_min_cut(n, edges, vertex_weights):
    """
    Compute minimum cut using max flow (Dinic's algorithm).

    Graph construction:
    - Source node 0, Sink node n+1 (nodes 1..n are the actual vertices)
    - S -> i with capacity vertex_weights[i-1]
    - u -> v and v -> u with capacity w for each edge (u,v,w)
    """
    INF = float('inf')

    # Number of nodes including source and sink
    num_nodes = n + 2
    source = 0
    sink = n + 1

    # Build graph
    graph = []  # Adjacency list
    for _ in range(num_nodes):
        graph.append({})

    def add_edge(u, v, cap):
        # Forward edge with capacity
        if v in graph[u]:
            graph[u][v] = {
                'cap': cap,
                'cap_orig': cap,
                'rev': graph[u][v],
                'gone': False
            }
        else:
            graph[u][v] = {
                'cap': cap,
                'cap_orig': cap,
                'rev': None,
                'gone': False
            }

        # Backward edge
        if u in graph[v]:
            graph[v][u]['cap'] += cap
            graph[v][u]['cap_orig'] += cap
        else:
            graph[v][u] = {
                'cap': 0,
                'cap_orig': 0,
                'rev': graph[u][v],
                'gone': False
            }

    # Add source to vertex edges
    for i in range(1, n + 1):
        add_edge(source, i, vertex_weights[i - 1])

    # Add vertex to vertex edges (for each input edge with bidirectional capacity)
    for u, v, w in edges:
        # u -> v with capacity w
        add_edge(u, v, w)
        # v -> u with capacity w
        add_edge(v, u, w)

    # Dinic's algorithm
    level = [-1] * num_nodes
    queue = [0]
    level[0] = 0

    def bfs():
        queue.clear()
        for i in range(num_nodes):
            level[i] = -1
        queue.append(source)
        level[source] = 0
        head = 0
        while head < len(queue):
            u = queue[head]
            head += 1
            for v, data in graph[u].items():
                if data['cap'] > 0 and level[v] < 0:
                    level[v] = level[u] + 1
                    queue.append(v)
        return level[sink] >= 0

    def dfs(u, pushed):
        if pushed == 0 or u == sink:
            return pushed
        for v, data in graph[u].items():
            if level[v] != level[u] + 1 or data['cap'] == 0:
                continue
            tr = dfs(v, min(pushed, data['cap_orig'] - data['cap']))
            if tr == 0:
                continue
            data['cap'] -= tr
            graph[v][data['rev']]['cap'] += tr
            return tr
        return 0

    max_flow = 0
    while bfs():
        ptr = [i for i in range(num_nodes)]
        while True:
            pushed = dfs(source, INF)
            if pushed == 0:
                break
            max_flow += pushed

    return max_flow

