    # Cannot form spanning tree with fewer edges than n-1
    if m < n - 1:
        return "-1\n"

    edges = []
    capital_indices = []

    for i in range(1, m + 1):
        if i >= len(lines):
            break
        try:
            parts = lines[i].split()
            a, b, w = int(parts[0]), int(parts[1]), int(parts[2])
            edges.append((a, b, w))
            if a == 1 or b == 1:
                capital_indices.append(i)
        except:
            continue

    if len(capital_indices) < k:
        return "-1\n"

    # Build index map
    index_map = {i: (edges[i-1], i) for i in capital_indices}

    all_edges = enumerate(edges, 1)
    capital_list = [(edges[i-1]['w'], i) for i in capital_indices]
    other_edges = [(edges[i]['w'], i) for i in range(1, m + 1) if i not in capital_indices]
    capital_list.sort()
    other_edges.sort()

    # Reconstruct edges with proper indexing
    edges_list = [(a, b, w, i) for i, (a, b, w) in enumerate(edges, 1)]

    best_solution = None
    best_weight = float('inf')

    for cap_combo in itertools.combinations(capital_indices, k):
        parent = list(range(n + 1))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx != ry:
                parent[ry] = rx
                return True
            return False

        total_weight = 0
        used_edges = set(cap_combo)

        # Union capital edges
        for idx in cap_combo:
            a, b, w, _ = edges_list[idx - 1]
            total_weight += w
            if not union(a, b):
                return "-1\n"

        # Add other edges
        edges_used_count = k
        for w, idx in other_edges:
            if edges_used_count == n - 1:
                break
            a, b, _ = edges_list[idx - 1]
            if union(a, b):
                total_weight += w
                edges_used_count += 1
                used_edges.add(idx)

        # Verify spanning tree
        components = len(set(find(i) for i in range(1, n + 1)))

        if components == 1 and total_weight < best_weight:
            best_weight = total_weight
            best_solution = sorted(list(used_edges))

    if best_solution is None:
        return "-1\n"

    return f"{len(best_solution)}\n{' '.join(map(str, best_solution))}\n"

