    """
    Solution for the lucky region problem.
    Finds minimum roads to build to make a lucky region.
    """
    lines = input_str.strip().split('\n')
    if not lines or not lines[0]:
        return '-1\n'

    n, m = map(int, lines[0].split())

    # Parent array for Union-Find
    parent = list(range(n + 1))

    # Path compression
    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:
            nxt = parent[x]
            parent[x] = root
            x = nxt
        return root

    # Union operation
    def union(x, y):
        rootx = find(x)
        rooty = find(y)
        if rootx != rooty:
            parent[rootx] = rooty

    # Process all edges
    for i in range(1, min(m + 1, len(lines))):
        line = lines[i].strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) >= 2:
            u, v = int(parts[0]), int(parts[1])
            union(u, v)

    # Count component sizes
    component_counts = [0] * (n + 1)
    for i in range(1, n + 1):
        root = find(i)
        component_counts[root] += 1

    component_sizes = [c for c in component_counts if c > 0]

    # Check if any component is already lucky
    def is_lucky(x):
        s = str(x)
        return all(c in '47' for c in s)

    if any(is_lucky(size) for size in component_sizes):
        return '0\n'

    # Generate all lucky numbers up to n
    lucky_numbers = set()
    for length in range(1, len(str(n)) + 1):
        for digit in '47':
            num = int(digit)
            for _ in range(length):
                num = num * 10
            # Actually generate properly
            pass

    lucky_numbers = set()
    def generate(start_num, length, max_len):
        if length == len(str(n)):
            return
        for digit in '47':
            new_num = start_num * 10 + int(digit)
            if new_num <= n:
                lucky_numbers.add(new_num)
                generate(new_num, length + 1, max_len)

    generate(0, 0, len(str(n)) + 1)
    lucky_numbers = sorted([x for x in lucky_numbers if x <= n])

    # Find minimum merges using BFS for each target lucky number
    min_ans = float('inf')

    for target in lucky_numbers:
        if target == 0:
            continue

        # BFS to find minimum number of components summing to target
        # State: (current_sum, num_components)
        queue = deque()
        min_components = {}  # sum -> min_components_used
        min_components[0] = 0
        queue.append((0, 0))

        found = False
        while queue:
            current_sum, count = queue.popleft()

            # Try adding each component
            for size in component_sizes:
                new_sum = current_sum + size
                if new_sum == target:
