    is_prime_small[0] = is_prime_small[1] = 0

    primes = []
    for i in range(2, sqrt_r + 1):
        if is_prime_small[i]:
            primes.append(i)
            for j in range(i*i, sqrt_r + 1, i):
                is_prime_small[j] = 0

    # Segmented sieve for range [l, r]
    n = r - l + 1
    is_prime_range = bytearray([1] * n)

    for p in primes:
        # Find first multiple of p >= l
        first = ((l + p - 1) // p) * p

        # Start at p*p if possible (primes >= p*p are composites)
        if first < p * p:
            first = p * p

        if first > r:
            break

        # Mark multiples of p in the range
        for j in range(first, r + 1, p):
            is_prime_range[j - l] = 0

    # If l itself is in the range and is a prime >= 2, it won't be marked
    # by any composite marking, which is correct

    # Count lucky primes (primes = 2 or prime % 4 == 1)
    count = 0
