    def rev(n):
        s = str(n)
        reversed_s = s[::-1]
        return int(reversed_s)

    def is_lucky(a, b):
        return a * b == rev(a) * rev(b)

    def count_lucky(x, y):
        c = 0
        for a in range(1, x + 1):
            for b in range(1, y + 1):
                if is_lucky(a, b):
                    c += 1
        return c

    best_x, best_y = -1, -1
    best_product = maxx * maxy + 1

    # Search for minimum x*y that achieves at least w lucky tickets
    found = False
    for x in range(1, maxx + 1):
        for y in range(1, maxy + 1):
            product = x * y
            if product >= best_product:
                continue
            if count_lucky(x, y) >= w:
                found = True
                best_x, best_y = x, y
                best_product = product
                best_product = x * y

    if not found:
        return '-1'
    else:
        return f'{best_x} {best_y}\n'

