            changes_needed = min(abs(x - (x // prime * prime)), x // prime * prime - x + prime)
            if changes_needed <= 1:
                change_cost += b
            else:
                change_cost += 2 * b  # Both sides

    min_cost = change_cost

    # Try removing segments
    for i in range(n):
        for j in range(i + 1, n + 1):  # Remove arr[i:j]
            removed_len = j - i
            if removed_len >= n:
                continue  # Can't remove everything

            # Remaining elements from [0, i) and [j, n)
            rem_count = i + (n - j)
            if rem_count == 0:
                continue

            segment_cost = removed_len * a

            # Cost for remaining elements
            remaining_cost = 0
            for k in range(i):
                x = arr[k]
                if x % prime != 0:
                    rem_count -= 1
