                        if x % prime != 0:
                            remaining_cost += b
            else:  # Only if we didn't break
                total = segment_cost + remaining_cost
                if total < min_cost:
                    min_cost = total

            # Optimization: break if segment cost already exceeds best
            if segment_cost >= min_cost:
                break

    return min_cost

