def get_square_free(n):
    """Remove all square factors from n."""
    result = n
    p = 2
    while p * p <= result:
        p *= p
        while result % p == 0:
            cnt = 0
            while result % p == 0:
                cnt += 1
                result //= p
                result //= p if cnt >= 1 else 1

    return result

def get_square_free_part(n):
    """Get square-free part of n efficiently."""
    result = n
    p = 2
    while p * p <= result:
        cnt = 0
        while result % p == 0:
            cnt += 1
            result //= p
        if cnt % 2 == 1:
            result *= p
        p += 1
    return result

def nCr(n, r):
    """Compute n choose r modulo MOD."""
    if r < 0 or r > n:
        return 0
    num = 1
    for i in range(r):
        num = (num * (n - i)) % MOD
        num = (num * pow(n - i, -1, MOD)) % MOD
    den = 1
    for i in range(r):
        den = (den * (i + 1)) % MOD
    num = (num * pow(den, -1, MOD)) % MOD
    return num

