    if n == 0:
        return "YES\n"

    index_map = {num: i for i, num in enumerate(p)}

    can_be_A = [0] * n
    can_be_B = [0] * n

    # Determine which set each number can belong to
    for i, num in enumerate(p):
        if a - num in index_map:
            can_be_A[i] = 1
        if b - num in index_map:
            can_be_B[i] = 1

    # Check if any number cannot be in either set
    for i in range(n):
        if can_be_A[i] == 0 and can_be_B[i] == 0:
            return "NO"

    # Union-Find to connect numbers that must be in the same set (those sharing an a-pair)
    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    # Connect numbers that have an a-pair (they must be in the same set if either is in A)
    for i in range(n):
        if can_be_A[i]:
            j = index_map[a - p[i]]
            union(i, j)

    # Group numbers by their component
    components = defaultdict(list)
    for i in range(n):
        components[find(i)].append(i)

    # Assign each component to either set A or B
    assignment = [0] * n
