def solution(input_str):
    n, m, r, k = map(int, input_str.strip().split())

    # Compute coverage counts: for each cell, how many scoop positions catch it
    # Row coverage at position i: how many valid scoop x-positions cover row i
    row_counts = [max(0, min(n - r, i) - max(0, i - r + 1) + 1) for i in range(n)]
    # Column coverage at position j: how many valid scoop y-positions cover column j
    col_counts = [max(0, min(m - r, j) - max(0, j - r + 1) + 1) for j in range(m)]

    # Sort for binary search
    row_counts.sort()
    col_counts.sort()

    total_positions = (n - r + 1) * (m - r + 1)
    k = min(k, n * m)

    # Binary search to find the kth largest product threshold
    left, right = 0, row_counts[-1] * col_counts[-1] + 1

    while left < right:
        mid = (left + right) // 2
        # Count products >= mid
        cnt = 0
        for rc in row_counts:
            if rc > 0 and mid > rc:
                cnt += bisect.bisect_right(col_counts, mid // rc)
            elif rc > 0:
                cnt += len(col_counts)

        if cnt >= k:
            left = mid + 1
        else:
            right = mid

    threshold = left - 1

    # Sum all products >= threshold
    above_k = 0
    for rc in row_counts:
        if rc > 0:
            idx = bisect.bisect_right(col_counts, threshold // rc) if threshold // rc > 0 else 0
            if idx > 0 and idx < len(col_counts) and col_counts[idx - 1] * rc >= threshold:
                for j in range(idx):
                    above_k += rc * col_counts[j]
                above_k += (threshold // rc) * (rc * len(col_counts) - above_k // (threshold // rc))
            # Simplified: just sum all where product >= threshold
            idx = bisect.bisect_right(col_counts, (threshold - 1) // rc)
            if rc > 0:
                above_k += sum(rc * cc for cc in col_counts[:idx])

    # Exact sum calculation
    total_sum = 0
    for rc in row_counts:
        if rc > 0:
            idx = bisect.bisect_right(col_counts, threshold // rc)
            count_products = idx
            if count_products >= k:
                for cc in col_counts[:k]:
                    total_sum += rc * cc
                break
            total_sum += sum(rc * cc for cc in col_counts[:count_products])
            k -= count_products

    # Add equal threshold products if needed
    if k > 0:
        same_count = 0
        for rc in row_counts:
            if rc > 0 and same_count < k:
                idx = bisect.bisect_right(col_counts, threshold // rc)
                if idx > 0:
                    actual_same = len([c for c in col_counts[:idx] if c * rc >= threshold])
                    take = min(actual_same, k)
                    total_sum += take * threshold
                    k -= take

    return f"{total_sum / total_positions:.10f}"

