def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    attempts = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        attempts.append((parts[0], int(parts[1])))

    count = 0

    def search(pos, current):
        nonlocal count

        # Pruning: Check if current partial assignment violates any constraint
        for attempt_code, c in attempts:
            current_matches = sum(current[i] == attempt_code[i] for i in range(pos))
            if current_matches > c:
                return

        if pos == n:
            # Verify all constraints on complete solution
            for attempt_code, c in attempts:
                matches = sum(current[i] == attempt_code[i] for i in range(n))
                if matches != c:
                    return
            count += 1
            return

        for bit in ['0', '1']:
            search(pos + 1, current + bit)

    search(0, '')
    return str(count)
